'use strict';

// MODULES //

var sin = require( '@stdlib/math/base/special/sin' );
var cos = require( '@stdlib/math/base/special/cos' );


// MAIN //

/**
* Computes the half-value coversed cosine.
*
* @param {number} x - input value (in radians)
* @returns {number} half-value coversed cosine
*
* @example
* var v = hacovercos( 0.0 );
* // returns 0.5
*
* @example
* var v = hacovercos( 3.141592653589793/2.0 );
* // returns 1.0
*
* @example
* var v = hacovercos( -3.141592653589793/6.0 );
* // returns 0.25
*
* @example
* var v = hacovercos( NaN );
* // returns NaN
*/
function hacovercos( x ) {
	var s;
	var c;

	s = sin( x );
	if ( s < 0.0 ) {
		// Where `sin(x)` is close to minus one, `1 + sin(x)` cancels. Use `1 + sin(x) = cos(x)^2 / (1 - sin(x))` where `sin(x) < 0`, since `cos(x)` is computed with full relative accuracy near its zeros and the denominator does not cancel:
		c = cos( x );
		return ( c * c ) / ( 2.0 * ( 1.0 - s ) );
	}
	return ( 1.0 + s ) / 2.0;
}


// EXPORTS //

module.exports = hacovercos;
